style.css:
@-moz-document domain("twitter.com"), domain("x.com") {
/* Background */
  body {
    background: url("https://media.discordapp.net/attachments/841022746107445308/1395167879825064141/fondo_x.png?ex=687976d7&is=68782557&hm=5b53ca2ea8bfcd27be03cc84aea3aef9f6ab458c2a94d2a04fdc8fdcd64d3c9a&=&format=webp&quality=lossless&width=1254&height=705") repeat !important;
    background-size: 150px 150px !important;
  }

  /* Sidebar container */
  header[role="banner"],
  nav[aria-label="Primary"],
  div[data-testid="sidebarColumn"],
  div[aria-label="Timeline: Trending now"] {
    background-color: rgba(255, 240, 250, 0.8) !important;
    backdrop-filter: blur(10px);
    border-radius: 20px;
    margin: 10px !important;
  }

  /* Sidebar icons */
  nav[aria-label="Primary"] a[role="link"]:before {
    content: "? ";
    font-size: 16px;
  }

  /* Font and color tweaks */
  * {
    font-family: "Comic Neue", "Segoe UI", sans-serif !important;
    color: #b35d9e !important;
  }

  /* Fix for media (images/videos) visibility */
  div[aria-label="Image"] img,
  img[src*="twimg.com"],
  div[data-testid="tweetPhoto"] img {
    opacity: 1 !important;
    display: block !important;
    visibility: visible !important;
    filter: none !important;
  }

  /* Profile picture rounded */
  img[alt*="Image"] {
    border-radius: 50% !important;
    border: 2px solid #ffc0cb !important;
  }

  /* Hide who-to-follow and ads */
  aside[aria-label="Who to follow"],
  div[data-testid="placementTracking"] {
    display: none !important;
  }

  /* Posts container transparency */
  main[role="main"] > div > div {
    background-color: rgba(255, 250, 255, 0.7) !important;
    border-radius: 15px;
    padding: 10px;
  }

  /* Macaron emoji decorations */
  nav[aria-label="Primary"]::after {
    content: "\1F36E \1F9C1 \1F370";
    font-size: 24px;
    position: absolute;
    left: 15px;
    bottom: 15px;
  }
}
